<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Snake</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <main class="app">
    <header class="top">
      <h1 class="title">Snake</h1>
      <div class="scores">
        <div class="stat">
          <span class="stat-label">Score</span>
          <span class="stat-value" id="score">0</span>
        </div>
        <div class="stat">
          <span class="stat-label">Best</span>
          <span class="stat-value" id="high-score">0</span>
        </div>
      </div>
    </header>

    <div class="board-wrap">
      <canvas id="board" aria-label="Snake game board" role="img"></canvas>
      <div class="overlay" id="overlay">
        <h2 class="overlay-title" id="overlay-title">Snake</h2>
        <p class="overlay-text" id="overlay-text">Press an arrow key to start.</p>
        <button type="button" class="btn btn-primary" id="overlay-action">Start</button>
      </div>
    </div>

    <footer class="controls">
      <p class="hint">Arrow keys to steer. Eat the red food to grow. Avoid walls and your own body.</p>
      <button type="button" class="btn btn-secondary" id="restart">New game</button>
    </footer>
  </main>

  <script src="app.js"></script>
</body>
</html>
