<file path="style.css">
*,
*::before,
*::after {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

:root {
  --bg: #0a0d12;
  --panel: #10151c;
  --text: #e6edf3;
  --muted: #9aa7b4;
  --snake: #3ddc84;
  --food: #ff4d5e;
  --border: #242c36;
  --focus: #ffffff;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

html,
body {
  height: 100%;
  margin: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.app {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  width: 100%;
  max-width: 520px;
}

.top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px 24px;
  width: min(92vw, 480px);
}

.title {
  margin: 0;
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.scores {
  display: flex;
  gap: 20px;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  min-width: 72px;
}

.stat-label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}

.stat-value {
  font-family: var(--mono);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--snake);
  font-variant-numeric: tabular-nums;
}

.board-wrap {
  position: relative;
  width: min(92vw, 480px);
}

#board {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 1 / 1;
  background: #06080b;
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 24px;
  text-align: center;
  background: rgba(10, 13, 18, 0.86);
  border-radius: 10px;
}

.overlay-title {
  margin: 0;
  font-size: 1.6rem;
  font-weight: 700;
}

.overlay-text {
  margin: 0;
  color: var(--muted);
  max-width: 28ch;
}

.controls {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  width: min(92vw, 480px);
}

.hint {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
  text-align: center;
}

.btn {
  font: inherit;
  font-weight: 600;
  padding: 10px 22px;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, transform 0.05s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.btn-primary {
  background: var(--snake);
  color: #06210f;
  border: 1px solid var(--snake);
}

.btn-primary:hover {
  background: #5ee7a0;
  border-color: #5ee7a0;
}

.btn-secondary {
  background: transparent;
  color: var(--text);
  border: 1px solid #3a4452;
}

.btn-secondary:hover {
  background: #17202a;
  border-color: #4a5566;
}

@media (max-width: 420px) {
  .title {
    font-size: 1.4rem;
  }

  .stat-value {
    font-size: 1.25rem;
  }
}
