<file path="app.js">
(function () {
  'use strict';

  var COLS = 20;
  var ROWS = 20;
  var CELL = 24;
  var TICK_MS = 120;
  var POINTS_PER_FOOD = 10;
  var STORAGE_KEY = 'snake.highScore';

  var DIRS = {
    ArrowUp: { x: 0, y: -1 },
    ArrowDown: { x: 0, y: 1 },
    ArrowLeft: { x: -1, y: 0 },
    ArrowRight: { x: 1, y: 0 }
  };

  var COLORS = {
    background: '#06080b',
    grid: '#0d1219',
    snake: '#3ddc84',
    head: '#7bffb0',
    food: '#ff4d5e'
  };

  var canvas = document.getElementById('board');
  var scoreEl = document.getElementById('score');
  var highEl = document.getElementById('high-score');
  var overlay = document.getElementById('overlay');
  var overlayTitle = document.getElementById('overlay-title');
  var overlayText = document.getElementById('overlay-text');
  var overlayAction = document.getElementById('overlay-action');
  var restartBtn = document.getElementById('restart');

  if (!canvas || !scoreEl || !highEl || !overlay || !overlayTitle ||
      !overlayText || !overlayAction || !restartBtn) {
    return;
  }

  var ctx = canvas.getContext('2d');
  if (!ctx) {
    return;
  }

  canvas.width = COLS * CELL;
  canvas.height = ROWS * CELL;

  var state = null;
  var timer = null;
  var highScore = loadHighScore();

  function loadHighScore() {
    try {
      var value = parseInt(window.localStorage.getItem(STORAGE_KEY), 10);
      return isNaN(value) || value < 0 ? 0 : value;
    } catch (e) {
      return 0;
    }
  }

  function saveHighScore(value) {
    try {
      window.localStorage.setItem(STORAGE_KEY, String(value));
    } catch (e) {
      // Storage unavailable; the score still works for this session.
    }
  }

  function createState() {
    var snake = [
      { x: 10, y: 10 },
      { x: 9, y: 10 },
      { x: 8, y: 10 }
    ];
    var s = {
      snake: snake,
      dir: { x: 1, y: 0 },
      queue: [],
      score: 0,
      food: null,
      status: 'ready'
    };
    s.food = spawnFood(snake);
    return s;
  }

  function spawnFood(snake) {
    var occupied = {};
    for (var i = 0; i < snake.length; i++) {
      occupied[snake[i].x + ',' + snake[i].y] = true;
    }
    var free = [];
    for (var y = 0; y < ROWS; y++) {
      for (var x = 0; x < COLS; x++) {
        if (!occupied[x + ',' + y]) {
          free.push({ x: x, y: y });
        }
      }
    }
    if (free.length === 0) {
      return null;
    }
    return free[Math.floor(Math.random() * free.length)];
  }

  function updateScoreDisplay() {
    scoreEl.textContent = String(state.score);
    highEl.textContent = String(highScore);
  }

  function showOverlay(title, text, buttonLabel) {
    overlayTitle.textContent = title;
    overlayText.textContent = text;
    overlayAction.textContent = buttonLabel;
    overlay.hidden = false;
  }

  function hideOverlay() {
    overlay.hidden = true;
  }

  function render() {
    ctx.fillStyle = COLORS.background;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = COLORS.grid;
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (var gx = 1; gx < COLS; gx++) {
      ctx.moveTo(gx * CELL + 0.5, 0);
      ctx.lineTo(gx * CELL + 0.5, canvas.height);
    }
    for (var gy = 1; gy < ROWS; gy++) {
      ctx.moveTo(0, gy * CELL + 0.5);
      ctx.lineTo(canvas.width, gy * CELL + 0.5);
    }
    ctx.stroke();

    if (state.food) {
      var fx = state.food.x * CELL + CELL / 2;
      var fy = state.food.y * CELL + CELL / 2;
      ctx.fillStyle = COLORS.food;
      ctx.beginPath();
      ctx.arc(fx, fy, CELL * 0.36, 0, Math.PI * 2);
      ctx.fill();
    }

    for (var i = 0; i < state.snake.length; i++) {
      var seg = state.snake[i];
      ctx.fillStyle = i === 0 ? COLORS.head : COLORS.snake;
      var pad = 2;
      roundRect(
        ctx,
        seg.x * CELL + pad,
        seg.y * CELL + pad,
        CELL - pad * 2,
        CELL - pad * 2,
        6
      );
      ctx.fill();
    }
  }

  function roundRect(c, x, y, w, h, r) {
    c.beginPath();
    c.moveTo(x + r, y);
    c.lineTo(x + w - r, y);
    c.arcTo(x + w, y, x + w, y + r, r);
    c.lineTo(x + w, y + h - r);
    c.arcTo(x + w, y + h, x + w - r, y + h, r);
    c.lineTo(x + r, y + h);
    c.arcTo(x, y + h, x, y + h - r, r);
    c.lineTo(x, y + r);
    c.arcTo(x, y, x + r, y, r);
    c.closePath();
  }

  function stopTimer() {
    if (timer !== null) {
      window.clearInterval(timer);
      timer = null;
    }
  }

  function startLoop() {
    stopTimer();
    timer = window.setInterval(tick, TICK_MS);
  }

  function beginRun() {
    if (state.status === 'running') {
      return;
    }
    state.status = 'running';
    hideOverlay();
    startLoop();
  }

  function newGame() {
    stopTimer();
    state = createState();
    updateScoreDisplay();
    render();
    beginRun();
  }

  function resetToReady() {
    stopTimer();
    state = createState();
    updateScoreDisplay();
    render();
    showOverlay('Snake', 'Press an arrow key to start.', 'Start');
  }

  function endGame(message) {
    stopTimer();
    state.status = 'over';
    if (state.score > highScore) {
      highScore = state.score;
      saveHighScore(highScore);
    }
    updateScoreDisplay();
    render();
    showOverlay(
      'Game over',
      message + '. Final score: ' + state.score + '.',
      'Play again'
    );
  }

  function tick() {
    if (!state || state.status !== 'running') {
      return;
    }

    var nd = state.queue.length ? state.queue.shift() : state.dir;
    state.dir = nd;

    var head = state.snake[0];
    var nx = head.x + nd.x;
    var ny = head.y + nd.y;

    if (nx < 0 || ny < 0 || nx >= COLS || ny >= ROWS) {
      endGame('You hit a wall');
      return;
    }

    var eating = state.food !== null && nx === state.food.x && ny === state.food.y;

    // When not eating, the tail moves away this tick, so it is not a collision.
    var bodyToCheck = eating ? state.snake : state.snake.slice(0, -1);
    for (var i = 0; i < bodyToCheck.length; i++) {
      if (bodyToCheck[i].x === nx && bodyToCheck[i].y === ny) {
        endGame('You ran into yourself');
        return;
      }
    }

    state.snake.unshift({ x: nx, y: ny });

    if (eating) {
      state.score += POINTS_PER_FOOD;
      state.food = spawnFood(state.snake);
      if (!state.food) {
        updateScoreDisplay();
        endGame('You filled the whole board');
        return;
      }
    } else {
      state.snake.pop();
    }

    updateScoreDisplay();
    render();
  }

  function handleDirection(d) {
    if (!state || state.status === 'over') {
      return;
    }
    var last = state.queue.length ? state.queue[state.queue.length - 1] : state.dir;
    if (d.x === last.x && d.y === last.y) {
      return;
    }
    if (d.x === -last.x && d.y === -last.y) {
      return;
    }
    if (state.queue.length >= 2) {
      return;
    }
    state.queue.push(d);
    if (state.status === 'ready') {
      beginRun();
    }
  }

  window.addEventListener('keydown', function (e) {
    if (Object.prototype.hasOwnProperty.call(DIRS, e.key)) {
      e.preventDefault();
      handleDirection(DIRS[e.key]);
    }
  });

  overlayAction.addEventListener('click', function () {
    newGame();
  });

  restartBtn.addEventListener('click', function () {
    newGame();
  });

  resetToReady();
})();
